// Additive currency/security translation of an existing dated conditional result.
// No operating, claim, share-count, FX forecast or current-price model is changed.
export const TSM_DATED_CONVERSION=Object.freeze({version:'2026-10-19-tsm-dated-ads-v1',date:'2026-09-30',reviewedAt:'2026-10-19',minimumInformationDate:'2026-10-17',twdPerUSD:31.880,ordinaryPerADS:5,ordinarySharesMillions:25932,currentInterestBearingDebtMillions:213198,longTermInterestBearingDebtMillions:818380,totalInterestBearingDebtMillions:1031578,financialStatementsURL:'https://investor.tsmc.com/english/encrypt/files/encrypt_file/reports/2026-10/3a94d1034b9e6b22446b674f7aaf3d088a12a193/FS.pdf',presentationURL:'https://www.sec.gov/Archives/edgar/data/1046179/000104617926000726/a3q26presentatione.htm'});
const finite=x=>typeof x==='number'&&Number.isFinite(x);
export function twdOrdinaryToDatedUSDADS(value){if(!finite(value))throw Error('A finite TWD ordinary-share value is required.');return value*TSM_DATED_CONVERSION.ordinaryPerADS/TSM_DATED_CONVERSION.twdPerUSD;}
export function datedUSDADSToTwdOrdinary(value){if(!finite(value))throw Error('A finite USD ADS value is required.');return value*TSM_DATED_CONVERSION.twdPerUSD/TSM_DATED_CONVERSION.ordinaryPerADS;}
export function calculateTsmDatedConversion(d,bridge){
 const f=TSM_DATED_CONVERSION;
 if(d?.ticker!=='TSM'||bridge?.ticker!=='TSM'||d.currency!=='TWD'||bridge.currency!=='TWD'||bridge.securityBasis!=='TWD ordinary share, issuer-rounded common count')throw Error('The dated conversion requires the reviewed TSM TWD ordinary-share basis.');
 if(d.timing?.mode!=='origin'||d.discountOrigin!==f.date||bridge.discountOrigin!==f.date||bridge.calculationDate!==f.date||bridge.capitalReferenceDate!==f.date||bridge.shareReferenceDate!==f.date)throw Error('The verified spot FX applies only to the September 30, 2026 operating and capital date.');
 if(typeof d.informationAsOf!=='string'||typeof bridge.informationAsOf!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(d.informationAsOf)||!/^\d{4}-\d{2}-\d{2}$/.test(bridge.informationAsOf)||d.informationAsOf<f.minimumInformationDate||bridge.informationAsOf<f.minimumInformationDate)throw Error('The source information date is incomplete or too early.');
 if(bridge.status!=='conditional'||bridge.eligible!==true||!finite(bridge.rawPerShare)||!finite(bridge.equity)||bridge.basicShares!==f.ordinarySharesMillions||!finite(bridge.allocationShares)||bridge.allocationShares<f.ordinarySharesMillions||!bridge.sources?.some(s=>s.url===f.financialStatementsURL&&s.date===f.date))throw Error('A complete reviewed dated ordinary-share allocation is required.');
 return {status:'dated-conditional-conversion',version:f.version,date:f.date,informationAsOf:d.informationAsOf,reviewedAt:f.reviewedAt,nativeCurrency:'TWD',nativeSecurityBasis:'ordinary share',nativePerShare:bridge.rawPerShare,currency:'USD',securityBasis:'ADS representing five ordinary shares',perADS:twdOrdinaryToDatedUSDADS(bridge.rawPerShare),twdPerUSD:f.twdPerUSD,ordinaryPerADS:f.ordinaryPerADS,priceComparisonEligible:false,currentValuationEligible:false,asKnownBacktestEligible:false,currentCapitalVerified:false,classification:'Currency translation of the dated conditional allocation; not a current USD target or an independently researched ADS valuation.',sources:[{url:f.financialStatementsURL,pdfPage:1,note:'(1)',fact:'September 30, 2026 spot exchange rate: TWD31.880 per USD.'},{url:f.financialStatementsURL,pdfPage:2,note:'(2)',fact:'One ADR represents five ordinary shares.'},{url:f.presentationURL,slide:7,printedPage:6,fact:'25,932m outstanding shares; TWD818,380m long-term interest-bearing debt. Current TWD213,198m plus long-term equals existing TWD1,031,578m debt.'}],limitations:['All original cash, claims, dilution and source-date limitations still apply.','The TWD48,065m difference between long-term interest-bearing debt and bonds has not been decomposed here; retained lease sensitivities may overlap and are not newly verified.','A dated spot translation is not current FX, an exchange-rate forecast, an ADS trading price, or a return estimate.']};
}
export function withTsmDatedConversion(d,bridge){
 if(d?.ticker!=='TSM'||!bridge)return bridge;
 try{const datedADSConversion=calculateTsmDatedConversion(d,bridge);return {...bridge,datedADSConversion,warnings:(bridge.warnings||[]).filter(x=>x!=='No valuation-date spot FX has been verified. USD ADS output remains blocked; flow-average FX is not a substitute.')};}
 catch(error){return {...bridge,datedADSConversion:{status:'unavailable',reason:error.message,perADS:null,priceComparisonEligible:false,currentValuationEligible:false,asKnownBacktestEligible:false}};}
}
